// AT-012 (M1.T11, R-012; journey J09 ⌘K): the palette on the 10,000-chat fixture database. Launch with the
// container holding `antichat.sqlite` generated by `tools/fixtures/gen-chats.py` (tools/at/at-012-probe.sh stages
// it; ANTICHAT_BIG10K_CONTAINER overrides). Blocked by Q-015 like the other XCUITests; the in-process probe
// (`-PaletteProbe`, App/AntiChat/PaletteProbe.swift) runs the same legs meanwhile (build/at/AT-012/probe-*/).
// Leg (2) "selecting the row opens Settings at that row" closes in M1.T22 (convention 9).
import XCTest

final class J09PaletteTests: XCTestCase {
    /// A fresh throwaway container holding a copy of the 10k fixture database (Q-015 catch-up: launching on a missing
    /// container silently ran on an empty database, and the tests wrote into the shared copy).
    static func container() throws -> URL {
        let env = ProcessInfo.processInfo.environment
        let db = env["ANTICHAT_BIG10K_DB"].map { URL(fileURLWithPath: $0) }
            ?? TurnApp.repoRoot.appendingPathComponent("build/fixtures/big-10k.sqlite")
        guard FileManager.default.fileExists(atPath: db.path) else {
            throw XCTSkip("no \(db.path): python3 -I tools/fixtures/gen-chats.py --chats 10000 --long 1:1000 --out build/fixtures/big-10k.sqlite")
        }
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent("antichat-uitest-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        try FileManager.default.copyItem(at: db, to: dir.appendingPathComponent("antichat.sqlite"))
        return dir
    }

    @MainActor
    private func launch() throws -> (XCUIApplication, XCUIElement) {
        let app = XCUIApplication.foreground()
        app.launchArguments = ["-ANTICHAT_DEV_CONTAINER", try Self.container().path, "-ApplePersistenceIgnoreState", "YES",
                               "-OfflineOnly", "YES"]
        app.launch()
        let window = app.mainWindow
        XCTAssertTrue(window.waitForExistence(timeout: 10))
        return (app, window)
    }

    private func element(_ window: XCUIElement, _ id: String) -> XCUIElement {
        window.descendants(matching: .any)[id]
    }

    /// (1) ⌘K → tabs All / Actions / Chats; a body-only token and a title word find their chats; footer hints.
    @MainActor
    func testSearchTitlesAndBodies() throws {
        let (app, window) = try launch()
        app.typeKey("k", modifierFlags: .command)
        XCTAssertTrue(element(window, "palette").waitForExistence(timeout: 1))
        for tab in ["all", "actions", "chats"] { XCTAssertTrue(element(window, "palette.tab.\(tab)").exists) }
        for hint in ["select", "open", "askTab", "close"] { XCTAssertTrue(element(window, "palette.hint.\(hint)").exists) }
        // M9.T05: the id names the search field itself (UP-CP-006), not the kit's whole view.
        XCTAssertEqual(element(window, "palette.field").elementType, .textField)
        app.typeText("zebracorn")
        let chatRows = window.descendants(matching: .any).matching(NSPredicate(format: "identifier BEGINSWITH 'palette.row.chat.'"))
        XCTAssertTrue(chatRows.firstMatch.waitForExistence(timeout: 1))
        XCTAssertEqual(chatRows.count, 1)
        for _ in 0..<9 { app.typeKey(.delete, modifierFlags: []) }
        app.typeText("pasta")
        XCTAssertTrue(chatRows.firstMatch.waitForExistence(timeout: 1))
        XCTAssertGreaterThan(chatRows.count, 0)
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertFalse(element(window, "palette").waitForExistence(timeout: 0.5))
    }

    /// Escape closes the palette wherever the focus is (spec S-18: "Escape, a click outside, activating a row and Tab
    /// close it"): at once after ⌘K, and after a tab chip took the focus away from the field (M9.T03).
    @MainActor
    func testEscapeClosesWhereverTheFocusIs() throws {
        let (app, window) = try launch()
        app.typeKey("k", modifierFlags: .command)
        XCTAssertTrue(element(window, "palette").waitForExistence(timeout: 1))
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertFalse(element(window, "palette").waitForExistence(timeout: 0.5), "Escape right after ⌘K")
        app.typeKey("k", modifierFlags: .command)
        XCTAssertTrue(element(window, "palette").waitForExistence(timeout: 1))
        element(window, "palette.tab.actions").click()
        app.typeKey(.escape, modifierFlags: [])
        XCTAssertFalse(element(window, "palette").waitForExistence(timeout: 0.5), "Escape after a tab chip click")
    }

    /// (2) Actions tab lists New chat, New incognito chat, every settings section, Switch chat; "send with" shows the
    /// General row "Send with".
    @MainActor
    func testActionsAndSettingsRows() throws {
        let (app, window) = try launch()
        app.typeKey("k", modifierFlags: .command)
        element(window, "palette.tab.actions").click()
        for id in ["action.newChat", "action.newIncognitoChat", "action.switchChat"]
            + ["general", "appearance", "capabilities", "evil", "voice", "personalization", "tools", "skills",
               "privacy", "storage", "updates", "shortcuts", "about"].map({ "action.settings.\($0)" }) {
            XCTAssertTrue(element(window, "palette.row.\(id)").exists || {
                window.scrollViews.firstMatch.scroll(byDeltaX: 0, deltaY: -400)
                return element(window, "palette.row.\(id)").waitForExistence(timeout: 0.5)
            }(), id)
        }
        element(window, "palette.tab.all").click()
        app.typeText("send with")
        XCTAssertTrue(element(window, "palette.row.setting.sendWithCommandEnter").waitForExistence(timeout: 1))
    }

    /// (2, M1.T22 forward leg) Selecting the "Send with" row opens Settings at that row.
    @MainActor
    func testSettingsRowOpensSettingsAtThatRow() throws {
        let (app, _) = try launch()
        app.typeKey("k", modifierFlags: .command)
        app.typeText("send with")
        app.typeKey(.downArrow, modifierFlags: [])
        app.typeKey(.return, modifierFlags: [])
        let settings = app.windows.containing(.any, identifier: "settings.root").firstMatch
        XCTAssertTrue(settings.waitForExistence(timeout: 3))
        XCTAssertTrue(element(settings, "settings.row.sendWithCommandEnter").waitForExistence(timeout: 1))
        XCTAssertTrue(element(settings, "settings.detail.general").exists)
    }

    /// (3) Tab creates a new chat with the query in the composer (not sent).
    @MainActor
    func testTabAsksInANewChat() throws {
        let (app, window) = try launch()
        app.typeKey("k", modifierFlags: .command)
        app.typeText("hello from the palette")
        app.typeKey(.tab, modifierFlags: [])
        XCTAssertFalse(element(window, "palette").waitForExistence(timeout: 0.5))
        XCTAssertTrue(element(window, "emptyHeadline").waitForExistence(timeout: 1))
        XCTAssertEqual(element(window, "composerText").value as? String, "hello from the palette")
    }
}
